    explicit LaserEntities(std::pmr::memory_resource& resource) noexcept
        : resource_{&resource} {}
    auto get_memory_resource() const noexcept -> std::pmr::memory_resource* { return resource_; }
    ~LaserEntities() { Operations::release_storage(*this); }
